'use strict';
const VERSION='scenario-2026-10-20-v21-pilot-checks';
const SCENARIO=Object.freeze({pilot_checks:'post_outcome_no_feedback',screen_format:'one_idea_or_question_per_screen',poll_decision:'lead_member_for_performance_video',poll2_decision:'lead_member_for_another_performance_video',vote_display:'animated_assigned_participation',stake_measure:'initial_number_of_voting_rights_held',other_fans:100,other_rights_per_poll:100,campaign_polls:2,first_platform_poll:true,same_candidates_in_poll2:true,repeat_winner_eligible:true,rights_expire_after_poll2:true,poll2_budget_cents:100,earlier_money_separate:true,discussion_topic:'group_upcoming_activities'});
const designs={
 rights:{label:'Voting rights and participation',short:'Rights × voting',hypothesis:'H1 and the design comparison',description:'Does a voting experience change intended purchases of voting rights differently when voting rights are single-use or reusable?',fixed:'Five initial rights; win/loss is randomized before the Poll 2 choice.',cells:[['single',5,true],['single',5,false],['reusable',5,true],['reusable',5,false]]},
 stake:{label:'Rights held and participation',short:'Holdings × voting',hypothesis:'H2 under single-use rights',description:'Is the voter–non-voter difference in intended purchases of voting rights smaller for large holders than for small holders?',fixed:'Single-use rights; win/loss is randomized before the Poll 2 choice.',cells:[['single',2,true],['single',2,false],['single',10,true],['single',10,false]]},
 outcome:{label:'Rights held and the vote outcome',short:'Holdings × outcome',hypothesis:'H3 under single-use rights',description:'Is the loss–win difference in intended purchases of voting rights more negative for large voters than for small voters?',fixed:'Single-use rights; all participants vote. An assigned win or loss precedes the final second-poll purchase decision.',cells:[['single',2,true,'win'],['single',2,true,'loss'],['single',10,true,'win'],['single',10,true,'loss']]}
};
const app=document.getElementById('app');
const REVIEW_MODE=document.body.dataset.mode==='review';
let selected='rights',run=null,step=0,view='overview';
let voteAnimationTimer=null;
const VOTE_ANIMATION_MS=1800;
const PILOT_ITEMS=Object.freeze([
 {id:'pilot_size',field:'perceived_initial_holding_size',kind:'rating',title:'Your initial voting rights',question:'How small or large did your initial number of voting rights seem?'},
 {id:'pilot_holdings',field:'initial_rights_recall',kind:'choice',title:'Your starting rights',question:'How many voting rights did you hold at the start of the scenario, before Poll 1?',options:[['0','0 rights'],['2','2 rights'],['5','5 rights'],['10','10 rights'],['unknown','I don’t remember']]},
 {id:'pilot_rule',field:'rule_application',kind:'choice',title:'The voting rule',question:'Imagine having 5 voting rights and using 3 in Poll 1. Under your voting rule, how many could you use in Poll 2 before buying more?',options:[['0','0 rights'],['2','2 rights'],['3','3 rights'],['5','5 rights'],['unknown','I’m not sure']]},
 {id:'pilot_participation',field:'participation_recall',kind:'choice',title:'Your first-poll participation',question:'In the scenario, did you vote in Poll 1?',options:[['voted','Yes, I voted'],['did_not_vote','No, I did not vote'],['unknown','I don’t remember']]},
 {id:'pilot_outcome',field:'outcome_recall',kind:'choice',title:'The first-poll result',question:'Did your preferred member, Choice A, win or lose Poll 1?',options:[['win','Won'],['loss','Lost'],['unknown','I don’t remember']]},
 {id:'pilot_purchase',field:'purchase_meaning',kind:'choice',title:'Your Poll 2 choice',question:'What did the number you selected for Poll 2 represent?',options:[['additional','Additional voting rights to buy'],['total','Total voting rights, including rights already held'],['past_votes','Votes already cast in Poll 1'],['unknown','I’m not sure']]}
]);
const SCREENS=Object.freeze([
 {id:'intro',label:'Start',event:'Introduction'},
 {id:'video',label:'The new video',event:'Video brief'},
 {id:'candidates',label:'The candidates',event:'Candidates'},
 {id:'holdings',label:'Your rights',event:'Your situation'},
 {id:'campaign',label:'Two polls',event:'Campaign'},
 {id:'rule',label:'Voting rule',event:'Voting rule'},
 {id:'rule_check',label:'Rule check',event:'Rule comprehension'},
 {id:'other_fans',label:'Other fans',event:'Other-fan context'},
 {id:'expected',label:'Your expectation',event:'Expectations'},
 {id:'vote',label:'Poll 1 vote',event:'First-poll voting'},
 {id:'result',label:'Poll 1 result',event:'First-poll win/loss'},
 {id:'influence',label:'Your influence',event:'Perceived influence'},
 {id:'disconfirmation',label:'Compared with expected',event:'Influence disconfirmation'},
 {id:'disappointment',label:'Your reaction',event:'Disappointment'},
 {id:'poll2',label:'The next video',event:'Second-poll introduction'},
 {id:'budget',label:'Your new budget',event:'Second-poll budget'},
 {id:'purchase',label:'Your purchase choice',event:'Second-poll choice'},
 {id:'social',label:'Fan discussion',event:'Fan discussion intention'},
 ...PILOT_ITEMS.map(item=>({id:item.id,label:item.title,event:'Pilot check: '+item.field})),
 {id:'finish',label:'Finish',event:'Debrief'}
]);
const money=c=>'$'+(c/100).toFixed(2);
const cellLabel=c=>`${c[0]==='single'?'Single-use':'Reusable'} · ${c[1]} rights · ${c[3]?(c[3]==='win'?'Win':'Loss'):(c[2]?'Voted':'Did not vote')}`;
function randomIndex(n){const limit=Math.floor(4294967296/n)*n;let x;do{x=crypto.getRandomValues(new Uint32Array(1))[0]}while(x>=limit);return x%n;}
function tokenStrip(available,used=0){return `<div class="tokens" aria-label="${available} available voting rights and ${used} used rights">${Array.from({length:available},()=>'<span class="token" aria-hidden="true">1</span>').join('')}${Array.from({length:used},()=>'<span class="token used" aria-hidden="true">×</span>').join('')}</div>`;}
function announce(){stopVoteAnimation();app.setAttribute('tabindex','-1');app.focus({preventScroll:true});window.scrollTo(0,0)}
function experienceFlow(){const labels=['Voting rights','Expectations','Poll 1 voting','Poll 1 result','Reaction','Poll 2 choice','Fan discussion'];return `<ol class="flow">${labels.map((label,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${label}</li>`).join('')}</ol>`;}
function showResearchLinks(visible){document.querySelectorAll('[data-research-only]').forEach(button=>{button.hidden=!(visible&&REVIEW_MODE);});}
function overview(){
 view='overview';showResearchLinks(true);
 if(!REVIEW_MODE){document.getElementById('leaveActivity').hidden=true;app.innerHTML=`<section class="sheet welcome-sheet"><div class="eyebrow">Fan community</div><h1>Welcome.</h1><p class="lead">Imagine helping a group plan its next performance video. Read each situation and tell us what you would think or do.</p><p class="fine">You may stop at any time.</p><div class="actions"><button class="primary" id="startCombined">Get started →</button></div></section>`;document.getElementById('startCombined').onclick=startCombined;return;}
 app.innerHTML=`<section class="hero"><div><div class="eyebrow">Fan voting · preview</div><h1>Imagine a fan vote.</h1><p class="lead">Read a short scenario. Choose what you would think and do.</p><div class="actions"><button class="primary" id="startCombined">Start →</button></div><p class="fine" style="margin-top:20px">Research-team preview only. Ethics approval is required before participant testing.</p></div><div class="rule-illustration"><h3>What you’ll do</h3><div class="rule-row"><b>1. Read</b><p class="fine">Learn how your voting rights work.</p></div><div class="rule-row"><b>2. Choose</b><p class="fine">Select your answers.</p></div><div class="rule-row"><b>3. Finish</b><p class="fine">Review your choices.</p></div></div></section><div class="notice"><p>This is a hypothetical scenario. No real purchases or votes take place.</p></div>`;
 document.getElementById('startCombined').onclick=startCombined;
}
function startCombined(){selected=Object.keys(designs)[randomIndex(3)];start('random',true);}
function research(){
 if(!REVIEW_MODE)return;
 view='research';showResearchLinks(true);const d=designs[selected];
 app.innerHTML=`<section class="hero"><div><div class="eyebrow">Researcher preview</div><h1>Three studies.<br>One common sequence.</h1><p class="lead">Everyone sees the first poll’s result before choosing for Poll 2.</p><p class="fine">The entry assigns one of three studies, then one of its four primary conditions. Studies 1 and 2 independently randomize win/loss within each condition. Study 3 includes win/loss in its holdings × outcome conditions. Cartoon mapping is independently counterbalanced.</p><p class="fine">Coauthor review only. Ethics approval is required before participant testing.</p></div><div class="rule-illustration"><h3>Different rules for your voting rights.</h3><p class="fine">Imagine holding 10 rights and casting 6 votes.</p><div class="rule-row"><b>Single-use</b>${tokenStrip(4,6)}<div class="fine">4 rights remain for the next poll.</div></div><div class="rule-row"><b>Reusable</b>${tokenStrip(10)}<div class="fine">All 10 rights remain for the next poll.</div></div></div></section><section class="section"><div class="sectiontop"><h2>Choose a study to review</h2><p class="fine">Four primary conditions per study</p></div><div class="cards">${Object.entries(designs).map(([key,d],i)=>`<article class="study-card ${selected===key?'selected':''}"><small>STUDY ${i+1}</small><h3>${d.label}</h3><p>${d.description}</p><p class="fine">${d.hypothesis}</p><button data-design="${key}" aria-pressed="${selected===key}">${selected===key?'Selected':'Review this design'}</button></article>`).join('')}</div></section><section class="section"><h2>The participant sequence</h2>${experienceFlow()}<div class="config preview-config"><div><label for="condition">${d.short}: preview condition</label><select id="condition"><option value="random">Random primary condition</option>${d.cells.map((c,i)=>`<option value="${i}">${cellLabel(c)}</option>`).join('')}</select><div class="fieldhint">${d.fixed}</div></div>${selected==='outcome'?'<div class="fieldhint">The selected condition determines the win/loss result.</div>':'<div><label for="resultPreview">Poll 1 result</label><select id="resultPreview"><option value="random">Random win or loss · 50/50</option><option value="win">Choice A wins</option><option value="loss">Choice B wins</option></select></div>'}<button class="primary" id="start">Start scenario →</button></div></section>`;
 app.querySelectorAll('[data-design]').forEach(b=>b.onclick=()=>{selected=b.dataset.design;research()});
 document.getElementById('start').onclick=()=>start(document.getElementById('condition').value,false,selected==='outcome'?'random':document.getElementById('resultPreview').value);
}
function start(choice,randomizedStudy=false,previewOutcome='random',previewAvatar='random'){
 const randomCondition=choice==='random',i=randomCondition?randomIndex(4):Number(choice);
 if(!Number.isInteger(i)||i<0||i>3)throw new Error('Invalid preview condition');
 const c=designs[selected].cells[i],outcomeFactor=selected==='outcome',randomOutcome=!outcomeFactor&&previewOutcome==='random';
 const outcome=outcomeFactor?c[3]:randomOutcome?['win','loss'][randomIndex(2)]:previewOutcome;
 if(!['win','loss'].includes(outcome))throw new Error('Invalid preview outcome');
 const randomAvatar=previewAvatar==='random',avatar=randomAvatar?['cat','rabbit'][randomIndex(2)]:previewAvatar;
 if(!['cat','rabbit'].includes(avatar))throw new Error('Invalid avatar');
 const primaryProbability=randomizedStudy&&randomCondition?1/12:null;
 const scenarioProbability=primaryProbability===null?null:primaryProbability*(randomOutcome?.5:1);
 run={version:VERSION,mode:REVIEW_MODE?'research_preview':'participant_preview',entry_route:randomizedStudy?'unified_random_entry':'researcher_preview',assignment_method:randomizedStudy?'browser_random_study_then_condition':randomCondition?'browser_random_condition_within_selected_study':'manual_preview',study_assignment_method:randomizedStudy?'browser_random_equal_probability':'manual_preview',study_assignment_probability:randomizedStudy?1/3:null,condition_assignment_method:randomCondition?'browser_random_equal_probability':'manual_preview',condition_assignment_probability:randomCondition?1/4:null,assignment_probability:primaryProbability,scenario_assignment_probability:scenarioProbability,presentation_assignment_probability:scenarioProbability===null?null:scenarioProbability*(randomAvatar?.5:1),outcome_assignment_method:outcomeFactor?'included_in_primary_condition':randomOutcome?'browser_random_equal_probability':'manual_preview',outcome_probability_given_condition:outcomeFactor?1:randomOutcome?.5:null,avatar_assignment_method:randomAvatar?'browser_random_equal_probability':'manual_preview',avatar_assignment_probability:randomAvatar?.5:null,avatar_for_a:avatar,avatar_for_b:avatar==='cat'?'rabbit':'cat',design:selected,condition_index:i,rights:c[0],initial_voting_rights:c[1],scenario_parameters:{...SCENARIO},scenario_voted:c[2],assigned_outcome:outcome,started_at:new Date().toISOString(),primary_outcome:{measure:'intended_second_poll_voting_right_purchases',timing:'after_assigned_first_poll_result',voting_rights:null,spending_cents:null},secondary_outcome:{measure:'intended_fan_discussion_participation',discussion_topic:SCENARIO.discussion_topic,timing:'after_assigned_first_poll_result',scale_min:1,scale_max:7,response:null},responses:{},comprehension_attempts:[],events:[]};
 step=0;view='study';renderStep();
}
function steps(){return SCREENS.map(screen=>screen.event);}
function participantSteps(){return SCREENS.map(screen=>screen.label);}
function screenId(){return SCREENS[step]?.id;}
function pilotScreen(item){
 const name='pilot_'+item.field;
 const question=item.kind==='rating'?scale(name,item.question,7,'Very small','Very large'):`<fieldset class="question"><legend>${item.question}</legend><div class="pilot-options">${item.options.map(([value,label])=>`<label class="pilot-option"><input type="radio" name="${name}" value="${value}"><span>${label}</span></label>`).join('')}</div></fieldset>`;
 return `<div class="eyebrow">About the scenario</div><h1>${item.title}</h1>${question}${nextButton()}`;
}
function savePilotAnswer(item){
 const raw=radio('pilot_'+item.field);
 if(raw===undefined)return fail('Please choose a response.');
 const value=item.kind==='rating'?Number(raw):raw;
 if(item.kind==='rating'?(!Number.isInteger(value)||value<1||value>7):!item.options.some(([option])=>option===value))return fail('Please choose a response.');
 if(!run.pilot_checks)run.pilot_checks={version:'pilot-checks-v1',timing:'after_primary_and_secondary_outcomes',started_at:new Date().toISOString(),responses:{},factual_results:{}};
 run.pilot_checks.responses[item.field]=value;
 if(item.kind!=='rating'){
  const expected={initial_rights_recall:String(run.initial_voting_rights),rule_application:run.rights==='single'?'2':'5',participation_recall:run.scenario_voted?'voted':'did_not_vote',outcome_recall:run.assigned_outcome,purchase_meaning:'additional'}[item.field];
  run.pilot_checks.factual_results[item.field]={response:value,expected,correct:value===expected,uncertain:value==='unknown'};
 }
 return true;
}
function completePilotChecks(){
 const checks=run.pilot_checks,results=Object.values(checks.factual_results);
 checks.completed_at=new Date().toISOString();
 checks.factual_summary={correct:results.filter(result=>result.correct).length,total:results.length,uncertain:results.filter(result=>result.uncertain).length};
}
function contextRecap(){return `<div class="context-recap" aria-label="Your scenario summary"><span>${run.rights==='single'?'Single-use rights':'Reusable rights'}</span><span>Initial rights: <b>${run.initial_voting_rights}</b></span></div>`;}
function compactFacts(items){return `<dl class="quick-facts">${items.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>`;}
function firstPurchaseSummary(){
 const cost=run.initial_voting_rights*5,refund=run.initial_voting_rights===10?40:0;
 return `<p>You bought <b>${run.initial_voting_rights} voting rights for ${money(cost)}</b>.${refund?' A one-time promotion refunded $0.40.':''}</p>${compactFacts([['Starting budget','$0.50'],['You paid (net)',money(cost-refund)],['Money left',money(50-cost+refund)]])}<p class="fine">Voting rights cannot be resold. Later purchases have no discount.</p>`;
}
function available(){return run.scenario_voted&&run.rights==='single'?0:run.initial_voting_rights;}
function scale(name,title,max=7,left='Not at all',right='Very much',middle=''){return `<div class="question"><fieldset><legend>${title}</legend><div class="scale scale-${max}">${Array.from({length:max},(_,i)=>`<label class="choice"><input type="radio" name="${name}" value="${i+1}">${i+1}</label>`).join('')}</div><div class="anchors ${middle?'anchors-three':''}"><span>1 = ${left}</span>${middle?`<span>4 = ${middle}</span>`:''}<span>${max} = ${right}</span></div></fieldset></div>`;}
function nextButton(text='Continue →'){return `<div class="error" role="alert" id="error"></div><div class="actions"><button class="primary" id="next">${text}</button></div>`;}


function votePictures(count,used=0){return `<div class="vote-pictures" aria-hidden="true">${Array.from({length:count},()=>'<span class="vote-disc">1</span>').join('')}${Array.from({length:used},()=>'<span class="vote-disc consumed">×</span>').join('')}</div>`;}
function holdingState(label,rights,used=0){return `<div class="holding-state" data-available="${rights}" data-used="${used}"><h3>${label}</h3><div class="holding-row">${votePictures(rights,used)}<strong>${rights} voting rights available${used?` · ${used} used up`:''}</strong></div></div>`;}
function votingDiagram(rights,cast,example=false){
 const used=run.rights==='single'?cast:0,remaining=rights-used;
 return `<figure class="experiment-visual voting-visual" aria-label="${example?'Example':'Your assigned situation'}: ${rights} voting rights before voting; ${cast} votes cast; ${remaining} voting rights available for the next poll."><figcaption>${example?'Example · 10 rights, 6 votes cast':'Your voting rights'}</figcaption><div class="holding-flow">${holdingState('Before voting',rights)}<div class="visual-arrow" aria-hidden="true">→</div>${holdingState('For the next poll',remaining,used)}</div><p class="visual-key">Circles = available rights${used?' · Crossed circles = used-up rights':''}</p></figure>`;
}
function avatarIcon(choice){
 const animal=choice==='A'?run.avatar_for_a:run.avatar_for_b;
 const head=animal==='cat'?'<path d="M18 29 16 10 31 18Q40 14 49 18L64 10 62 29Q68 55 40 56Q12 55 18 29Z"/>':'<path d="M24 28C14 8 23 0 29 12L36 27M44 27 51 12C57 0 66 8 56 28"/><ellipse cx="40" cy="39" rx="24" ry="19"/>';
 return `<svg class="member-icon avatar-icon" data-avatar="${animal}" data-avatar-choice="${choice}" viewBox="0 0 80 88" aria-hidden="true"><path d="M19 83V73c0-13 9-22 21-22s21 9 21 22v10Z"/>${head}<circle class="avatar-eye" cx="31" cy="37" r="1.5"/><circle class="avatar-eye" cx="49" cy="37" r="1.5"/><path class="avatar-face" d="m37 44 3 3 3-3M40 47v4"/></svg>`;
}
function candidatePanel(choice,winner=null){
 const chosen=winner===choice,status=winner===null?'pending':chosen?'selected':'not-selected';
 return `<div class="purpose-candidate ${winner?'result-candidate':''} ${chosen?'candidate-winner':''}" data-choice="${choice}" data-status="${status}">${avatarIcon(choice)}<h3>Choice ${choice}<span>${choice==='A'?'Your preferred member':'The other member'}</span></h3>${winner?`<span class="candidate-status">${chosen?'Winner':'Did not win'}</span>`:''}</div>`;
}
function performanceStoryboard(winner=null){
 const lead=winner?'Choice '+winner:'Lead not selected';
 const stage='<svg class="story-shot" viewBox="0 0 88 82" aria-hidden="true"><path d="M10 12h68v55H10zM10 22h68M22 12l-6 10m23-10-6 10m23-10-6 10m23-10-6 10M21 58h46M27 50h34M33 42h22"/><path d="m39 29 13 7-13 7z"/></svg>';
 const end='<svg class="story-shot" viewBox="0 0 88 82" aria-hidden="true"><path d="M10 12h68v55H10zM18 57h52M24 49h40M30 41h28M24 17l8 17m32-17-8 17M38 17l2 12m10-12-2 12"/><path d="M15 70h58"/></svg>';
 return `<div class="video-storyboard" data-storyboard-choice="${winner??'unknown'}"><div class="storyboard-title"><span class="storyboard-kicker">Performance video</span><strong>The video plan</strong></div><div class="storyboard-frames"><div class="storyboard-shot"><span class="shot-label">01 · Opening</span>${stage}</div><div class="storyboard-lead ${winner?'is-decided':''}"><span class="shot-label">02 · Lead part</span><div class="lead-slot">${winner?avatarIcon(winner):'<span class="lead-unknown" aria-hidden="true">?</span>'}</div><strong>${lead}</strong></div><div class="storyboard-shot"><span class="shot-label">03 · Finale</span>${end}</div></div><p class="storyboard-caption">${winner?'The winning member takes the lead.':'Fans choose the member for the lead part.'}</p></div>`;
}
function pollPurposeGraphic(){return `<figure class="experiment-visual poll-purpose" aria-label="Choice A represents your preferred member and Choice B the other member. The winning member takes the lead in the new performance video."><figcaption>What your votes help decide</figcaption><div class="poll-purpose-flow"><div class="purpose-candidates">${candidatePanel('A')}${candidatePanel('B')}</div><div class="purpose-arrow"><span>More votes</span><svg viewBox="0 0 64 30" aria-hidden="true"><path d="M2 15h58M49 5l11 10-11 10"/></svg></div>${performanceStoryboard()}</div></figure>`;}
function voteIllustration(){
 const rights=run.initial_voting_rights,cast=run.scenario_voted?rights:0,remaining=available(),used=run.rights==='single'?cast:0;
 const rule=run.scenario_voted?(run.rights==='single'?'Used rights are consumed.':'Your rights can be used again in Poll 2.'):'Your voting rights remain available.';
 const interval=cast?VOTE_ANIMATION_MS/cast:0,flight=Math.min(450,interval);
 const moving=Array.from({length:cast},(_,i)=>`<span class="cast-moving-token" style="--vote-delay:${interval*(i+1)-flight}ms;--vote-flight:${flight}ms"></span>`).join('');
 return `<figure class="experiment-visual cast-visual" data-illustration="assigned-vote" data-cast="${cast}" aria-label="You cast ${cast} votes for Choice A and have ${remaining} rights for Poll 2."><figcaption>Your Poll 1 participation</figcaption><div class="cast-flow" aria-hidden="true"><div class="cast-party cast-wallet" data-before-rights="${rights}"><h3>Your voting rights</h3><div class="cast-token-row" data-vote-wallet>${votePictures(rights-used,used)}</div><strong><span data-wallet-counter>${rights-used}</span> available rights</strong></div><div class="cast-route ${run.scenario_voted?'cast-active':'cast-idle'}"><span class="cast-route-label"><span data-cast-counter>${cast}</span> votes cast</span><div class="cast-track">${run.scenario_voted?'<svg viewBox="0 0 100 30"><path d="M2 15h90M79 5l13 10-13 10"/></svg>'+moving:'<svg viewBox="0 0 100 30"><path d="M5 15h90" stroke-dasharray="5 6"/></svg>'}</div></div><div class="cast-party cast-recipient"><h3>Choice A</h3>${avatarIcon('A')}<strong><span class="cast-vote-count" data-cast-counter>${cast}</span> votes from you</strong></div></div><div class="cast-balance rights-balance" data-available="${remaining}" aria-hidden="true"><div><span>Voting rights for Poll 2</span><strong data-balance-counter>${remaining}</strong></div></div><p class="cast-rule">${rule}</p></figure>`;
}
function stopVoteAnimation(){if(voteAnimationTimer!==null){clearTimeout(voteAnimationTimer);voteAnimationTimer=null;}}
function animateVoteIllustration(){
 const root=app.querySelector('[data-illustration="assigned-vote"]');
 if(!root||!run.scenario_voted||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const initial=run.initial_voting_rights,total=Number(root.dataset.cast),single=run.rights==='single';
 const paint=cast=>{const used=single?cast:0;root.querySelector('[data-vote-wallet]').innerHTML=votePictures(initial-used,used);root.querySelector('[data-wallet-counter]').textContent=initial-used;root.querySelectorAll('[data-cast-counter]').forEach(node=>node.textContent=cast);root.querySelector('[data-balance-counter]').textContent=initial-used;root.dataset.shownCast=String(cast);};
 let cast=0;paint(cast);
 const tick=()=>{if(!root.isConnected){voteAnimationTimer=null;return;}paint(++cast);if(cast<total)voteAnimationTimer=setTimeout(tick,VOTE_ANIMATION_MS/total);else voteAnimationTimer=null;};
 voteAnimationTimer=setTimeout(tick,VOTE_ANIMATION_MS/total);
}
function pollResult(outcome=run.assigned_outcome){
 const winner=outcome==='win'?'A':'B';
 return `<figure class="experiment-visual poll-visual" data-result="${outcome}" data-winner="${winner}"><figcaption>Poll 1 · result</figcaption><div class="poll-result-layout"><div class="purpose-candidates">${candidatePanel('A',winner)}${candidatePanel('B',winner)}</div>${performanceStoryboard(winner)}</div><p class="poll-summary"><b>Choice ${winner} won.</b> ${outcome==='win'?'Your preferred member':'The other member'} will take the lead in the new performance video.</p></figure>`;
}
function budgetUnits(value){return Array.from({length:20},(_,i)=>`<span class="budget-unit ${value===null?'unanswered':i<value?'spent':'retained'}" aria-hidden="true"></span>`).join('');}
function allocationVisual(){return `<figure class="experiment-visual allocation-visual"><figcaption>Your $1.00 budget</figcaption><div class="budget-rail" id="budgetRail" role="img" aria-label="Choose how many voting rights to buy to see the spending.">${budgetUnits(null)}</div><p class="visual-key">Each box = $0.05 · Hatched = spend · Empty = keep.</p><div class="allocation-totals" aria-live="polite"><div><strong id="cost">—</strong><span>You spend</span></div><div><strong id="retain">—</strong><span>You keep</span></div></div><div class="token-equation" aria-live="polite"><div><strong>${available()}</strong><span>Rights you have</span></div><b aria-hidden="true">+</b><div><strong id="newRights">—</strong><span>New rights</span></div><b aria-hidden="true">=</b><div><strong id="total">—</strong><span>Rights for Poll 2</span></div></div></figure>`;}
function inventory(after=false){const used=after&&run.rights==='single'&&run.scenario_voted?run.initial_voting_rights:0;return `<figure class="experiment-visual wallet-visual"><figcaption>${run.rights==='single'?'Single-use':'Reusable'} voting rights</figcaption>${holdingState('Your voting rights',after?available():run.initial_voting_rights,used)}</figure>`;}
function renderStep(){
 view='study';showResearchLinks(false);const screen=screenId(),labels=participantSteps();let content='';
 if(!REVIEW_MODE)document.getElementById('leaveActivity').hidden=screen==='finish';
 if(screen==='intro')content=`<div class="eyebrow">Before you start</div><h1>Keep your preferred member in mind.</h1><p>Think of a K-pop group you like and the member you most support. <b>Choice A</b> represents your preferred member; <b>Choice B</b> represents the other member.</p><p>Imagine taking part in each situation. No real purchases or votes take place.</p><label class="check"><input type="checkbox" id="ack"><span>I understand this is a hypothetical scenario.</span></label>${nextButton()}`;
 if(screen==='video')content=`<div class="eyebrow">The upcoming video</div><h1>Help shape the next video.</h1><p>The group is preparing a new performance video. <b>Fans will choose its lead member.</b></p>${performanceStoryboard()}${nextButton()}`;
 if(screen==='candidates')content=`<div class="eyebrow">Poll 1</div><h1>Who takes the lead?</h1><p>Fans choose between Choice A and Choice B. <b>The member with more votes takes the lead in the video.</b></p><div class="purpose-candidates standalone-candidates">${candidatePanel('A')}${candidatePanel('B')}</div>${nextButton()}`;
 if(screen==='holdings')content=`<div class="eyebrow">Your fan platform</div><h1>Your voting rights</h1><p>This is your first poll on this fan platform. You can buy voting rights. <b>Each right lets you cast one vote in a poll.</b></p>${firstPurchaseSummary()}${inventory()}<p class="fine">Fan discussions are free to join, regardless of how many voting rights you hold.</p>${nextButton()}`;
 if(screen==='campaign')content=`<div class="eyebrow">The campaign</div><h1>Two polls, one week apart.</h1><div class="campaign-cards"><div><small>Poll 1</small><h3>The first video</h3><p>Choose its lead member.</p></div><div class="campaign-gap" aria-hidden="true">One week later →</div><div><small>Poll 2</small><h3>Another video</h3><p>Choose its lead member.</p></div></div><p>The same two members compete again. <b>Either can win Poll 2, including Poll 1’s winner.</b> The voting rule and price per right stay the same.</p><p>All rights expire after Poll 2, when this campaign ends.</p>${nextButton()}`;
 if(screen==='rule')content=`<div class="eyebrow">Your voting rule</div><h1>${run.rights==='single'?'Single-use voting rights':'Reusable voting rights'}</h1><p>${run.rights==='single'?'<b>Each right can be used once.</b> Casting a vote uses up one right. Unused rights carry over to Poll 2.':'<b>Each right gives one vote in each of the two polls.</b> Voting in Poll 1 leaves your rights available for Poll 2.'}</p><p>You can use each right at most once per poll and use several rights for the same choice.</p>${votingDiagram(10,6,true)}${nextButton()}`;
 if(screen==='rule_check')content=`<div class="eyebrow">Your voting rule</div><h1>A quick check</h1><fieldset class="question"><legend>You have 10 voting rights and cast 6 votes. How many rights can you use in the next poll, before buying more?</legend><div class="scale">${[0,4,6,10].map(n=>`<label class="choice"><input name="comprehension" type="radio" value="${n}">${n}</label>`).join('')}</div></fieldset>${nextButton()}`;
 if(screen==='other_fans')content=`<div class="eyebrow">Poll 1</div><h1>Other fans also vote.</h1><p>The same <b>${SCENARIO.other_fans} other fans</b> can vote in both polls. Together, they have <b>${SCENARIO.other_rights_per_poll} rights available per poll</b>.</p><p>Their choices are unknown.</p>${nextButton()}`;
 if(screen==='expected')content=`<div class="eyebrow">Before Poll 1</div><h1>What do you expect?</h1>${scale('expected_influence','How much influence do you expect your voting rights to give you in this poll?',7,'None','A great deal')}${nextButton()}`;
 if(screen==='vote')content=`<div class="eyebrow">Poll 1 · voting</div><h1>${run.scenario_voted?'You voted.':'You did not vote.'}</h1><p>${run.scenario_voted?`You used all ${run.initial_voting_rights} voting rights to vote for Choice A.`:'You cast no votes.'} You followed the poll updates until it closed.</p>${voteIllustration()}${nextButton()}`;
 if(screen==='result')content=`<div class="eyebrow">Poll 1 · result</div><h1>The winning choice</h1>${pollResult()}${nextButton()}`;
 const resultReminder=`<p class="question-context">Choice A, your preferred member, ${run.assigned_outcome==='win'?'won':'lost'} Poll 1.</p>`;
 if(screen==='influence')content=`<div class="eyebrow">After Poll 1</div><h1>Your influence</h1>${resultReminder}${scale('perceived_influence','How much influence would you feel you had over the result?',7,'None','A great deal')}${nextButton()}`;
 if(screen==='disconfirmation')content=`<div class="eyebrow">After Poll 1</div><h1>Compared with your expectation</h1>${resultReminder}${scale('influence_disconfirmation','Compared with what you expected, how much influence would you feel you had?',7,'Much less','Much more','As expected')}${nextButton()}`;
 if(screen==='disappointment')content=`<div class="eyebrow">After Poll 1</div><h1>Your reaction</h1>${resultReminder}${scale('disappointment','How disappointed would you feel?',7,'Not at all','Very disappointed')}${nextButton()}`;
 if(screen==='poll2')content=`<div class="eyebrow">Poll 2 · next week</div><h1>Another performance video.</h1><p>Choice A ${run.assigned_outcome==='win'?'won':'lost'} Poll 1. <b>Poll 2 selects the lead for another performance video.</b> The same two members compete again; either can win.</p>${performanceStoryboard()}${nextButton()}`;
 if(screen==='budget')content=`<div class="eyebrow">Poll 2</div><h1>Your new spending budget</h1>${compactFacts([['Poll 2 spending budget',money(SCENARIO.poll2_budget_cents)],['Price per right','$0.05'],['Rights you have',available()]])}<p><b>This $1.00 is your full budget for this purchase.</b> Money left from your earlier budget is saved separately. Keep any of this $1.00 that you do not spend.</p><p>Each additional right lets you cast one more vote under your voting rule.</p>${nextButton()}`;
 if(screen==='purchase')content=purchase();
 if(screen==='social')content=`<div class="eyebrow">Fan community</div><h1>Joining the discussion</h1>${scale('social_participation_intention','How likely are you to join a fan discussion about the group’s upcoming activities on this platform next week?',7,'Very unlikely','Very likely')}${nextButton()}`;
 const pilotItem=PILOT_ITEMS.find(item=>item.id===screen);if(pilotItem)content=pilotScreen(pilotItem);
 if(screen==='finish')content=debrief();
 const recap=step>=4&&screen!=='finish'&&!pilotItem?contextRecap():'';
 app.innerHTML=`<div class="study-layout">${REVIEW_MODE?`<aside class="sidebar"><div class="aside-label eyebrow">Your scenario</div><ol>${labels.map((l,i)=>`<li class="${i===step?'current':''}" ${i===step?'aria-current="step"':''}><span class="index">${String(i+1).padStart(2,'0')}</span>${l}</li>`).join('')}</ol></aside>`:''}<section class="sheet" data-screen="${screen}"><div class="step-count">Step ${step+1} of ${labels.length}</div><div class="progress" role="progressbar" aria-label="Activity progress" aria-valuemin="0" aria-valuemax="${labels.length}" aria-valuenow="${step+1}"><div style="width:${100*(step+1)/labels.length}%"></div></div>${recap}${content}</section></div>`;
 if(document.getElementById('next'))document.getElementById('next').onclick=advance;
 if(document.getElementById('rightsQuantity')){document.getElementById('rightsQuantity').onchange=()=>{document.getElementById('error').textContent='';updateLedger();};updateLedger();}
 if(document.getElementById('download'))document.getElementById('download').onclick=download;
 if(document.getElementById('return'))document.getElementById('return').onclick=()=>{const manual=run.entry_route==='researcher_preview';run=null;manual?research():overview();announce();};
 announce();if(screen==='vote')animateVoteIllustration();
}
function purchase(){
 return `<div class="eyebrow">Poll 2</div><h1>Your purchase choice</h1><p class="purchase-reminder">$1.00 budget · $0.05 per right · ${available()} rights already available</p><div class="question"><label for="rightsQuantity"><b>How many additional voting rights would you buy?</b> Choose 0–20.</label><select id="rightsQuantity" class="rights-quantity" aria-label="Additional voting rights" required><option value="" disabled selected>Select the number of rights</option>${Array.from({length:21},(_,n)=>`<option value="${n}">${n} ${n===1?'right':'rights'}</option>`).join('')}</select>${allocationVisual()}</div>${nextButton()}`;
}
function updateLedger(){const el=document.getElementById('rightsQuantity'),n=Number(el.value),valid=el.value!==''&&Number.isInteger(n)&&n>=0&&n<=20;document.getElementById('cost').textContent=valid?money(5*n):'—';document.getElementById('retain').textContent=valid?money(100-5*n):'—';document.getElementById('total').textContent=valid?available()+n:'—';document.getElementById('newRights').textContent=valid?n:'—';const rail=document.getElementById('budgetRail');rail.innerHTML=budgetUnits(valid?n:null);rail.setAttribute('aria-label',valid?`Of your $1.00 budget, ${money(5*n)} is spent and ${money(100-5*n)} is retained.`:'Choose how many voting rights to buy to see the spending.');}
function radio(name){return app.querySelector(`input[name="${name}"]:checked`)?.value;}
function fail(msg){document.getElementById('error').textContent=msg;return false;}
function advance(){
 if(!run||run.completed_at||screenId()==='finish')return false;
 const screen=screenId(),r=run.responses,readRating=name=>{const value=Number(radio(name));return Number.isInteger(value)&&value>=1&&value<=7?value:null;};
 if(screen==='intro'&&!document.getElementById('ack').checked)return fail('Please confirm that you understand this is a hypothetical scenario.');
 if(screen==='rule_check'){const x=radio('comprehension');if(x===undefined)return fail('Please select an answer.');const correct=Number(x)===(run.rights==='single'?4:10);run.comprehension_attempts.push({answer:Number(x),correct});if(!correct)return fail(`Under your rule, ${run.rights==='single'?'used rights are consumed, so 4 remain':'rights can be used again, so all 10 remain'}. Please try again.`);r.comprehension_first_correct=run.comprehension_attempts[0].correct;}
 const ratingFields={expected:'expected_influence',influence:'perceived_influence',disconfirmation:'influence_disconfirmation',disappointment:'disappointment',social:'social_participation_intention'};
 if(ratingFields[screen]){const name=ratingFields[screen],value=readRating(name);if(value===null)return fail('Please choose a response.');r[name]=value;if(screen==='social'){run.secondary_outcome.response=value;run.main_outcomes_completed_at=new Date().toISOString();}}
 if(screen==='purchase'){const el=document.getElementById('rightsQuantity'),n=Number(el.value);if(el.value===''||!Number.isInteger(n)||n<0||n>20)return fail('Please select the number of voting rights, from 0 to 20.');r.voting_rights_poll2=n;r.spending_poll2_cents=n*5;run.primary_outcome.voting_rights=n;run.primary_outcome.spending_cents=n*5;}
 const pilotItem=PILOT_ITEMS.find(item=>item.id===screen);if(pilotItem&&savePilotAnswer(pilotItem)===false)return false;
 run.events.push({step:steps()[step],screen_id:screen,completed_at:new Date().toISOString()});step++;if(screenId()==='finish'){completePilotChecks();run.completed_at=new Date().toISOString();}renderStep();
}
function debrief(){
 if(!REVIEW_MODE)return `<div class="completion-mark" aria-hidden="true">✓</div><div class="eyebrow">Activity complete</div><h1>Thank you.</h1><p>You have completed the activity. You may close this page.</p><div class="completion-note"><p>This activity explores choices in online fan communities. The situations and poll results were assigned for the activity, not taken from live polls.</p><p>No real purchases or votes took place.</p></div>`;
 return `<div class="eyebrow">Preview complete</div><h1>Thank you.</h1><p>This study examines how voting rules and experiences affect intended purchases and fan participation. People receive different scenarios.</p><p>Download a test record to keep your answers.</p><table class="notetable"><tbody><tr><th>Poll 2 choice</th><th>Voting rights</th><th>Spending</th></tr><tr><td>After the Poll 1 result</td><td>${run.responses.voting_rights_poll2}</td><td>${money(run.responses.spending_poll2_cents)}</td></tr></tbody></table><p>Likelihood of joining a fan discussion: <b>${run.responses.social_participation_intention} / 7</b></p><p>Pilot factual checks: <b>${run.pilot_checks.factual_summary.correct} / ${run.pilot_checks.factual_summary.total}</b>; unsure/not recalled: ${run.pilot_checks.factual_summary.uncertain}. Perceived initial holding size: ${run.pilot_checks.responses.perceived_initial_holding_size} / 7. No exclusion threshold is applied.</p><details><summary>Researcher assignment details</summary><p class="fine">${designs[selected].short}<br>${cellLabel(designs[selected].cells[run.condition_index])}<br>Result: Choice ${run.assigned_outcome==='win'?'A':'B'} won<br>Choice A cartoon: ${run.avatar_for_a}<br>Assignment: ${run.assignment_method}<br>Version: ${VERSION}</p></details><div class="actions"><button class="primary" id="download">Download test record</button><button id="return">${run.entry_route==='researcher_preview'?'Return to researcher preview':'Return to entry'}</button></div>`;
}
function download(){const blob=new Blob([JSON.stringify(run,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`fan-voting-${selected}-preview.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function notes(){
 if(!REVIEW_MODE)return;
 view='notes';showResearchLinks(true);
 app.innerHTML=`<div class="eyebrow">Researcher design notes</div><h1>Expectations, results, and subsequent choices</h1><p class="lead">All three studies use 25 short screens with one idea or question per screen. Six pilot checks follow both main outcomes and precede the debrief. The measurement order is unchanged: expectation, assigned voting history, first-poll result, perceived influence, disconfirmation, disappointment, Poll 2 purchases, and discussion intention.</p>
 <h2>Study conditions and result assignment</h2><table class="notetable"><thead><tr><th>Study</th><th>Four primary conditions</th><th>First-poll result</th></tr></thead><tbody><tr><td>1 · Voting rights</td><td>Single-use or reusable rights × voted or did not vote; five initial rights.</td><td>Win/loss is independently randomized 50/50 within each condition.</td></tr><tr><td>2 · Stake</td><td>Two or ten initial rights × voted or did not vote; single-use rights.</td><td>Win/loss is independently randomized 50/50 within each condition.</td></tr><tr><td>3 · Outcome</td><td>Two or ten initial rights × win or loss; all voted with single-use rights.</td><td>Win/loss is part of the random condition; 50/50 within each stake level.</td></tr></tbody></table><p>Each participant receives one study with probability 1/3 and one primary condition with probability 1/4. Studies 1 and 2 have eight realized condition–result combinations each; Study 3 has four. The primary-condition probability is 1/12 overall. A realized condition–result combination has probability 1/24 in Studies 1/2 or 1/12 in Study 3. These probabilities are recorded separately. Results are assigned before responses and do not depend on expectations, purchases, or voting choices.</p><p>The cat/rabbit mapping to Choices A and B is separately randomized 50/50. Choice A always represents the participant’s preferred member. The record includes both avatar assignments and the complete presentation probability. Manual previews are identified separately and must not be mixed with random assignments.</p>
 <h2>End-of-pilot checks</h2><p>After the purchase and discussion responses, participants answer six questions one at a time: perceived initial holding size, initial-rights recall, a fresh voting-rule example, participation recall, win/loss recall, and the meaning of the purchase quantity. The holding-size rating is subjective and is not scored for correctness. Five factual responses are compared with the assigned scenario only in the researcher record.</p><p>Checks hide the rule/holdings recap. They allow unsure/not-recalled responses, accept any valid selection without corrective feedback, and do not filter, reassign, or exclude participants. They do not establish a causal mechanism or guarantee comprehension. Do not select a sample based on hypothesis-supporting feelings or purchase intentions. Check data are stored separately in pilot_checks, not the main outcome fields. main_outcomes_completed_at marks completion before these checks; final completion follows the checks.</p><h2>Expectation disconfirmation</h2><p>Before the result, participants report how much influence they expect their voting rights to give them: 1 = None, 7 = A great deal. After the result, they report perceived influence using the same anchors, then compare that influence with their expectation: 1 = Much less, 4 = As expected, 7 = Much more. Disappointment follows. There is no winning-probability forecast; losing alone is not treated as negative disconfirmation.</p><p>These measured process variables concern expected and perceived influence, not actual pivotal influence. They do not independently identify a causal effect of expectations or causal mediation. Prespecify the directional contrasts and process analyses before data collection.</p>
 <h2>Purchases and social participation</h2><p>All participants see the Poll 1 result before the Poll 2 purchase question. There is one purchase decision: 0–20 additional rights at $0.05 each from a new $1.00 budget. The earlier preliminary purchase question has been removed. The $1.00 is the complete Poll 2 purchase budget; earlier unspent money is saved separately and cannot be added. The secondary item asks how likely participants are to join a discussion of the group’s upcoming activities on this platform next week, from 1 (Very unlikely) to 7 (Very likely). Discussions are free and access is independent of rights holdings. This is a stated intention rather than observed engagement or the field peer-transfer measure.</p>
 <h2>Voting-right holdings and the campaign</h2><p>Stake is defined as the initial number of voting rights held: two versus ten in Studies 2 and 3. Net initial spending is held at $0.10 and cash remaining at $0.40 using the existing one-time refund for the larger bundle. Report the refund with the holding manipulation. Rights cannot be resold.</p><p>All participants imagine their first poll on this platform. The campaign has two polls, one week apart, and all rights expire after Poll 2. Each right can be used at most once in a poll; multiple rights can support one choice. Single-use rights are consumed when used and unused rights carry over. Reusable rights permit one vote in each of the two polls.</p><p>The same two members compete in both polls and a previous winner remains eligible. The same 100 other fans have 100 rights available in total in each poll. Their choices and turnout are unknown. These counts are fixed scenario assumptions, not observed vote totals or win probabilities; pilot their credibility and comprehension.</p>
 <h2>Contrasts and graphics</h2><p>Both polls select the lead member for an upcoming performance video. The storyboard makes the consequence concrete: the chosen member occupies the lead part. Voting is an assigned history, not a voluntary action. The 1.8-second display animates only the participant’s assigned votes and available-right balances; it adds no live turnout or vote totals. Reduced-motion settings show the final summary immediately, and participants may continue at any time.</p><p>H1 compares voters and non-voters under single-use rights and contrasts that difference with reusable rights. H2 compares the voter–non-voter difference across holding levels. H3 compares the loss–win difference across holding levels. Prespecify whether H1/H2 average over randomized outcomes and report any outcome interactions separately. Social-participation predictions require their own rationale.</p><p>Cartoons have the same neutral expression, pose, and styling. The initial diagram shows both choices and an unknown winner. The result screen identifies the winning choice and places that avatar into the video storyboard’s lead position. No fabricated vote counts or probabilities are shown. Voting remains an assigned scenario rather than an actual ballot.</p>
 <h2>Review and data collection</h2><p>This unlisted browser prototype keeps answers in page memory; a download saves a local JSON test record. Version 21 appends six Continue-controlled pilot checks after the main outcomes and hides the recap during these checks. Version 20 separated the content and questions into Continue-controlled screens and added a factual rule/initial-holdings recap. Version 19 replaced the banner scenario with performance-video lead selection and added a presentation-only voting animation. Initial holdings, costs, participation assignments, win/loss assignments, cartoon mapping, questions, outcome timing, and randomization probabilities are unchanged. Version 17 separated the participant-facing page from this coauthor review page. The default page shows no condition selectors, design notes, assignment details, test downloads, or future-step sidebar. The study assignments, question wording and scales, and amounts are unchanged. Screen-level event records now include a screen_id; presentation and reading effort differ from earlier versions. Both interfaces remain demonstrations with no server-side response collection; participant-facing presentation is not approval to recruit. The review page remains unlisted but is not access-controlled. Records distinguish participant_preview from research_preview. It removes expected_win_likelihood from new records and replaces outcome_disconfirmation with influence_disconfirmation to match the revised influence-focused questions. Earlier versions differ in outcome timing and questionnaire structure and should not be pooled without accounting for those changes.</p><p>Update the protocol and consent materials, finalize power and preregistration, and obtain ethics approval before participant testing. Live use requires server assignment, secure response storage, withdrawal/recruitment procedures, and removal of manual researcher controls. The scenario isolates voting-right rules and does not test blockchain-specific features.</p><div class="actions"><button class="primary" id="overviewReturn">Back to overview →</button></div>`;
 document.getElementById('overviewReturn').onclick=()=>{overview();announce()};announce();
}
function navigate(next){if(view==='study'&&run&&!run.completed_at&&!confirm('Leave this preview? The current test responses will be discarded.'))return;run=null;next==='notes'?notes():next==='research'?research():overview();announce();}
function leaveActivity(){if(!run||run.completed_at)return;if(!confirm('Leave this activity? Your answers on this page will be cleared.'))return;run=null;step=0;view='left';document.getElementById('leaveActivity').hidden=true;app.innerHTML='<section class="sheet welcome-sheet"><div class="eyebrow">Activity ended</div><h1>You have left the activity.</h1><p>Your answers on this page have been cleared. You may close this page.</p></section>';announce();}
if(REVIEW_MODE){document.getElementById('brand').onclick=e=>{e.preventDefault();navigate('overview')};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));}else document.getElementById('leaveActivity').onclick=leaveActivity;
overview();
